def max_Abs_Diff(arr):
    if len(arr) < 2:
        return None

    min_val = arr[0]
    max_diff = float('-inf')

    for num in arr:
        diff = abs(num - min_val)
        if diff > max_diff:
            max_diff = diff

        # Update minimum value seen so far to maximize future differences with larger numbers
        if num < min_val:
            min_val = num

    return int(max_diff)
